.gzp-desk{
          baggrund:
            radial-gradient(120% 70% ved 50% 0%, rgba(214.178.110,.05), transparent 58%),
            radial-gradient (130% 100% ved 50% 108%, rgba(0,0,0,.34), gennemsigtig 62%),
            /* trækorn — bredt og uregelmæssigt fordelt (gamle hårgrænser
               Det lignede fløjl) */
            repeating-linear-gradient(92deg,
              rgba(0,0,0,.13) 0 3px,
              gennemsigtig 3px 17px,
              rgba(255,255,255,.016) 17px 20px,
              gennemsigtig 20px 41px,
              rgba(0,0,0,.09) 41px 43px,
              gennemsigtig 43px 74px),
            /* samlinger af brædder */
            repeterende-lineær-gradient(90deg,
              rgba(0,0,0,.42) 0 2px,
              gennemsigtig 2px 148px),
            lineær gradient(180 grader, #33261a 0%, #291e13 52%, #1c150d 100%);
        }
        .gzp-under{
          position: absolut;
          indsat: 0;
          baggrund: lineær-gradient(180deg, #e6d9b6 0%, #d6c599 100%);
          box-shadow: 0 12px 22px rgba(0,0,0,.45), indsat 0 0 0 1px rgba(120,90,36,.2);
          transform: rotate(-1,15deg) translateY(5px);
        }
        .gzp-under--2{
          baggrund: lineær gradient(180deg, #e1d2ab 0%, #cfbd90 100%);
          transform: rotate(.85deg) translateY(9px);
        }
